mapper.select:
SELECT
    bo.*,
    s.supplier_name
FROM booking_order bo
LEFT JOIN supplier s ON bo.supplier_id = s.id AND s.deleted = 0
WHERE bo.deleted = 0

    AND bo.supplier_id = #{supplierId}


    AND bo.status = #{status}


    AND bo.booking_date = #{bookingDate}

ORDER BY bo.create_time DESC
